// Turns the router LLM reply into clean, validated fields for the chart step.
const chatId = $('Telegram Trigger1').first().json.message.chat.id;
const raw = String($json.text ?? $json.output ?? '').trim();

const ASK = 'ধন্যবাদ! কোন স্টকের চার্ট ও টেকনিক্যাল বিশ্লেষণ চান? Ticker লিখুন (যেমন AAPL, TSLA বা NYSE:KO)।';
const BAD = 'Ticker বুঝতে পারিনি। অনুগ্রহ করে সঠিক ticker লিখুন (যেমন AAPL বা NYSE:KO)।';
const chat = (reply) => ({ json: { intent: 'chat', symbol: '', interval: '', reply, chat_id: chatId } });

let p = null;
const m = raw.match(/\{[\s\S]*\}/);
if (m) { try { p = JSON.parse(m[0]); } catch (e) { p = null; } }

if (!p) {
  // Model ignored the JSON format: send its text only if it is a normal reply.
  const looksLikeJson = raw.startsWith('{') || raw.includes('"intent"');
  return chat(raw && !looksLikeJson ? raw : ASK);
}

if (String(p.intent || '').toLowerCase() !== 'analysis') {
  return chat(String(p.reply || '').trim() || ASK);
}

// Symbol: UPPERCASE EXCHANGE:TICKER (default exchange NASDAQ), strictly validated.
let symbol = String(p.symbol || '').trim().toUpperCase().replace(/\s+/g, '');
if (symbol && !symbol.includes(':')) symbol = 'NASDAQ:' + symbol;
if (!/^[A-Z0-9_]{2,15}:[A-Z0-9._!-]{1,20}$/.test(symbol)) return chat(BAD);

// Interval: normalise to chart-img values. "1M" (month) and "1m" (minute) differ, so keep 1M as is.
const MAP = { '1d': '1D', d: '1D', daily: '1D', day: '1D',
              '1w': '1W', w: '1W', weekly: '1W', week: '1W',
              '1mo': '1M', monthly: '1M', month: '1M',
              '4h': '4h', '1h': '1h', '15m': '15m', '30m': '30m' };
const rawInt = String(p.interval || '').trim();
const interval = rawInt === '1M' ? '1M' : (MAP[rawInt.toLowerCase()] || '1W');

return { json: { intent: 'analysis', symbol, interval, reply: '', chat_id: chatId } };

