// Telegram limit = 4096 chars, so long replies are split safely.
const MAX = 3800;
const chatId = $('Telegram Trigger1').first().json.message.chat.id;
const FALLBACK = 'দুঃখিত, কোনো বিশ্লেষণ তৈরি করা যায়নি। একটু পরে আবার চেষ্টা করুন।';
const results = [];
const push = (t) => {
  if (t && t.trim()) results.push({ json: { chat_id: chatId, clean_output: t.trim() } });
};

// Works for the Gemini "Analyze image" result and for the plain chat reply.
const pickText = (j) => {
  const parts = j.content?.parts;
  if (Array.isArray(parts)) {
    const t = parts.filter((x) => x && x.text && !x.thought).map((x) => x.text).join('\n');
    if (t.trim()) return t;
  }
  return j.reply ?? j.text ?? j.output ?? '';
};

for (const item of $input.all()) {
  let text = String(pickText(item.json)).trim();

  // Markdown -> plain text. Dots, hyphens, % etc. are kept so prices like 182.45 stay intact.
  text = text
    .replace(/\\n/g, '\n')
    .replace(/\*\*(.+?)\*\*/gs, '$1')
    .replace(/__(.+?)__/gs, '$1')
    .replace(/`{1,3}/g, '')
    .replace(/^[ \t]{0,3}#{1,6}[ \t]*/gm, '')
    .replace(/^[ \t]*[*\-][ \t]+/gm, '• ')
    .replace(/\*/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (!text) text = FALLBACK;

  let chunk = '';
  for (const para of text.split(/\n\n/)) {
    if (chunk && (chunk + '\n\n' + para).length > MAX) {
      push(chunk);
      chunk = '';
    }
    chunk = chunk ? chunk + '\n\n' + para : para;
    while (chunk.length > MAX) {
      push(chunk.slice(0, MAX));
      chunk = chunk.slice(MAX);
    }
  }
  push(chunk);
}

return results;
